import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0027 — Slides: presentazione di note","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0027-slides-note.md","filePath":"adr/0027-slides-note.md"}'),n={name:"adr/0027-slides-note.md"};function r(d,e,s,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0027-—-slides-presentazione-di-note" tabindex="-1">ADR-0027 — Slides: presentazione di note <a class="header-anchor" href="#adr-0027-—-slides-presentazione-di-note" aria-label="Permalink to &quot;ADR-0027 — Slides: presentazione di note&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §2.3.3, §4.1, §4.2, Appendice B (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-28</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (riga <code>slides</code>, P2), Appendice B (post-1.0); V-02/D-01, V-07/D-07; ADR-0004, ADR-0005, ADR-0026</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì (§2.2.1 riga <code>slides</code>: da P2 a P1; Appendice B: Slides esce dal post-1.0) → richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Il mockup della shell (ADR-0026) include nella sidebar destra una tab <em>ShowSlide</em> per configurare la presentazione del documento aperto: slide, effetti, note del presentatore. Lo spec classifica Slides come P2 post-1.0, con la sola indicazione «separatore <code>---</code>». Si decide di implementarla in M8, quindi lo spec va allineato.</p><p>Vincoli: finestra singola (V-07, niente schermo presentatore su finestra separata), nessun CSS personalizzato e HTML sanificato con DOMPurify (V-02), funzionamento offline, doppio parser con fixture condivise (<code>shared/conformance/</code>), file ordinari compatibili con Obsidian.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Modello.</strong> Una nota è una presentazione: le slide sono i blocchi separati da una riga <code>---</code> che segue una riga vuota (o è la prima del corpo) e sta fuori dal frontmatter, dai blocchi di codice (<code>```</code> e <code>~~~</code>) e dai blocchi math (<code>$$</code>). La riga vuota prima è una scelta: <code>---</code> subito sotto un testo è un titolo setext, non un separatore (il comando «Inserisci separatore» la produce già così). Le note del presentatore sono le righe che seguono una riga <code>Note:</code> (anche con testo sulla stessa riga, maiuscole indifferenti, fuori da codice e math) fino alla fine della slide. Una slide senza contenuto è scartata. Il contenuto resta Markdown/OFM ordinario: una nota senza <code>---</code> è una presentazione a una slide e si legge normalmente.</p><p><strong>Configurazione.</strong> Nel frontmatter, come proprietà piatte (scelta rispetto a un oggetto <code>slide:</code> annidato: l&#39;API delle proprietà modifica valori semplici e il pannello Proprietà le mostra già): <code>slide-transition</code> (<code>none|fade|slide|zoom</code>, default <code>slide</code>), <code>slide-theme</code> (<code>auto|light|dark</code>, default <code>auto</code>), <code>slide-progress</code> (booleano, default <code>true</code>), <code>slide-numbers</code> (booleano, default <code>false</code>), <code>slide-notes</code> (booleano, default <code>true</code>: mostra le note nella vista presentatore). Valori non validi tornano al default; chiavi sconosciute sono ignorate. Nessun nuovo file in <code>.memobrain/</code>: la configurazione viaggia con la nota e si sincronizza come <code>.md</code>.</p><p><strong>Parser.</strong> Estrazione delle slide in <code>packages/markdown</code> (TS) con equivalente Go in <code>apps/desktop/internal/parser</code> (oggi senza consumatori a runtime: serve a tenere i due parser allineati, come per le altre fixture), verificati con le stesse fixture in <code>shared/conformance/slides/</code> (CI bloccante). Ogni slide riporta la riga (1-based, frontmatter incluso) della sua prima riga non vuota, il contenuto e le note. Rendering con la pipeline reading (remark/rehype) già usata dall&#39;anteprima; HTML sanificato con DOMPurify, nessun <code>style</code> inline.</p><p><strong>Presentazione.</strong> Modalità a tutto schermo nella stessa finestra (overlay con <code>requestFullscreen</code> sul contenitore): navigazione da tastiera (frecce, spazio, Home/End), Esc per uscire, vista presentatore alternabile con slide corrente, successiva, note e timer. Comandi <code>slides:start</code> e <code>slides:start-here</code> nel registro. Nessuna richiesta di rete (verificata dalla CI come per Excalidraw).</p><p><strong>UI.</strong> Tab <em>ShowSlide</em> nella sidebar destra: opzioni sopra, miniature navigabili sotto; le modifiche scrivono il frontmatter attraverso lo stesso percorso delle Proprietà.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>reveal.js come dipendenza</strong> — scartata: peso, CSS e temi propri in conflitto con V-02; la pipeline reading esistente basta per un sottoinsieme.</li><li><strong>Slide in file <code>.slides</code> dedicati</strong> — scartata: rompe la compatibilità con i vault Obsidian e il merge a 3 vie dei <code>.md</code>.</li><li><strong>Finestra separata per il presentatore</strong> — scartata: V-07.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Slides entra in 1.0+ come P1: da riportare nella matrice §2.2.1 e nell&#39;Appendice B, e da coprire in <code>docs/qa/</code> (checklist di parità).</li><li>Il vincolo «Separatore <code>---</code>» dello spec è confermato; le note del presentatore e le chiavi <code>slide-*</code> sono estensioni di MemoBrain, non compatibili con i plugin Obsidian di slide (che le ignorano senza danno).</li><li>Un nuovo punto di contatto tra i due parser: ogni modifica alla sintassi richiede aggiornare le fixture in entrambi i linguaggi.</li></ul>',15)])])}const g=o(n,[["render",r]]);export{m as __pageData,g as default};
